CREATE TABLE IF NOT EXISTS `dashboard_templates` (
  `id` int AUTO_INCREMENT PRIMARY KEY,
  `name` varchar(100) NOT NULL,
  `description` text,
  `templateType` enum('system', 'shared') NOT NULL DEFAULT 'shared',
  `widgets` json NOT NULL,
  `layout` json NOT NULL,
  `previewImageUrl` text,
  `isPublic` boolean NOT NULL DEFAULT true,
  `createdBy` int NOT NULL,
  `usageCount` int NOT NULL DEFAULT 0,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

CREATE INDEX `idx_dashboard_templates_type` ON `dashboard_templates` (`templateType`);
CREATE INDEX `idx_dashboard_templates_public` ON `dashboard_templates` (`isPublic`);
CREATE INDEX `idx_dashboard_templates_creator` ON `dashboard_templates` (`createdBy`);
CREATE INDEX `idx_dashboard_templates_usage` ON `dashboard_templates` (`usageCount`);

